      candidates: live.sort((p, q) => p.cpuPricePerSec6 < q.cpuPricePerSec6 ? -1 : 1).slice(0, 8).map((h) => ({ id: h.id, endpoint: h.endpoint, cpuNodePerHour: usdHr2(h.cpuPricePerSec6) }))
