        throw new IndependentError("grant", `ownerSignature is not ${owner}'s SessionGrant signature over exactly this grant for vault ${vault2}`);
      const data = encodeFunctionData2({ abi: S3.sessionVaultFactoryAbi, functionName: "openFor", args: [owner, req.grant, a.ownerSignature] });
      const sim = await simulate(B3, { to: b4.factory, data });
